<template><div class="metrics"><div class="metric" v-for="m in metrics" :key="m.label"><span>{{m.label}}</span><b>{{m.prefix}}{{m.value}}</b><small>{{m.desc}}</small></div></div><div class="panel notes"><h3>鲜果铺运营重点</h3><div class="notes-grid"><div><b>单位与规格</b><p>每个 SKU 独立设置购买单位、规格、最小购买量与步进，避免所有水果统一按“斤”售卖。</p></div><div><b>全国化商品</b><p>商品按品类、品种和产地管理，不绑定城市，配送范围交给后续运费模板和仓配系统。</p></div><div><b>库存安全</b><p>创建订单时在数据库事务内扣库存，防止并发超卖；正式支付应再加支付回调幂等。</p></div></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../api';const d=ref<any>({});onMounted(async()=>d.value=await api.get('/admin/dashboard'));const metrics=computed(()=>[{label:'商品总数',value:d.value.products||0,prefix:'',desc:`在售 ${d.value.onSale||0}`},{label:'累计订单',value:d.value.orders||0,prefix:'',desc:`待处理 ${d.value.pending||0}`},{label:'用户数',value:d.value.users||0,prefix:'',desc:'微信用户'},{label:'累计 GMV',value:Number(d.value.gmV||0).toFixed(2),prefix:'¥',desc:'已支付口径'}])</script>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:20px}.metric{background:#fff;border:1px solid #e9ece7;border-radius:14px;padding:22px}.metric span,.metric small{display:block}.metric span{font-size:12px;color:#909992}.metric b{font-size:30px;display:block;margin:12px 0 8px}.metric small{font-size:11px;color:#adb3ae}.notes h3{margin-top:0}.notes-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.notes-grid>div{background:#f7f9f6;border-radius:11px;padding:18px}.notes-grid b{font-size:14px}.notes-grid p{font-size:12px;color:#78817b;line-height:1.7;margin-bottom:0}</style>
